#[component]
pub fn Icon(icon: IconKind, #[props(default = 20)] size: u32) -> Element {
    let path = spec(icon);
    rsx! {
        svg {
            xmlns: "http://www.w3.org/2000/svg",
            view_box: "0 0 24 24",
            fill: "currentColor",
            width: "{size}",
            height: "{size}",
            "aria-hidden": "true",
            path {
                d: path.d,
                fill_rule: if path.evenodd { "evenodd" },
                clip_rule: if path.evenodd { "evenodd" },
            }
        }
    }
}

#[component]
pub fn IconButton(
    icon: IconKind,
    #[props(default = 20)] size: u32,
    #[props(default)] class: Option<String>,
    #[props(default)] title: Option<String>,
    onclick: EventHandler<MouseEvent>,
) -> Element {
    rsx! {
        button {
            class: class.unwrap_or_default(),
            title: title.unwrap_or_default(),
            r#type: "button",
            onclick: move |evt| onclick.call(evt),
            Icon { icon, size }
        }
    }
}
